def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    my_d = 0
    for me, op in history:
        if me == 'D':
            my_d += 1
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1

    w = min(8, n)
    rec_opp_c = 0
    for me, op in history[n - w:]:
        if op == 'C':
            rec_opp_c += 1

    dc = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            dc += 1

    last_me, last_opp = history[-1]

    if n >= 30 and last_opp == 'C' and last_me == 'D' and opp_d <= 1 and rec_opp_c >= 6:
        return 'D'

    if last_opp == 'C':
        return 'C'

    if opp_c == 0:
        return 'D'
    if opp_d > opp_c + 8:
        return 'D'

    opp_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_streak += 1
        i -= 1

    nice = opp_c > opp_d or rec_opp_c >= 5
    if not nice:
        return 'D'

    provoked = False
    if last_me == 'D':
        provoked = True
    elif n >= 2 and history[-2][0] == 'D':
        provoked = True
    elif n >= 3 and history[-3][0] == 'D':
        provoked = True

    if last_me == 'D' and opp_streak <= 3 and rec_opp_c >= 1:
        return 'C'

    if provoked and opp_streak == 1:
        return 'C'

    if opp_c > opp_d and opp_streak == 2:
        if rng.random() < 0.2:
            return 'C'

    if opp_c > opp_d * 2 and opp_streak >= 3:
        if rng.random() < 0.1:
            return 'C'

    if provoked and opp_streak == 2 and last_me == 'C' and rec_opp_c >= 3:
        if rng.random() < 0.15:
            return 'C'

    return 'D'
